INSERT IGNORE INTO notices (notice_id,author_id,title,content,view_count) VALUES (1,1,'2026년 상반기 법정의무교육 안내','2026년 상반기 법정의무교육 수강 기간은 1월 1일부터 6월 30일까지입니다. 기간 내 반드시 이수해 주시기 바랍니다.',24);
INSERT IGNORE INTO notices (notice_id,author_id,title,content,view_count) VALUES (2,1,'시스템 점검 안내 (6/15)','2026년 6월 15일 오전 2시-4시 시스템 정기 점검이 있습니다. 해당 시간에는 LMS 접속이 불가합니다.',11);
INSERT IGNORE INTO notices (notice_id,author_id,title,content,view_count) VALUES (3,1,'스마트팩토리 교육 신규 오픈','현장 직원 대상 스마트팩토리 기초 운용 강좌가 신규 오픈되었습니다. 3월 1일부터 수강 신청 가능합니다.',18);
